<script setup>
import { computed, ref, onMounted } from 'vue'; import {useRoute} from 'vue-router'; import {catalog} from '../state'; import {api,date,time,money} from '../api'; import {ArrowRight,CalendarDays,MapPin,UserRound,Sprout,Heart,Flower2} from 'lucide-vue-next'
const route=useRoute(), course=computed(()=>catalog.value.courses.find(c=>c.id===Number(route.params.id))),sessions=ref([]),error=ref('')
const available=computed(()=>sessions.value.filter(s=>s.courseId===course.value?.id)),next=computed(()=>available.value[0])
onMounted(async()=>{try{sessions.value=await api('/sessions')}catch(e){error.value=e.message}})
</script>
<template><section v-if="course" class="container section"><p class="breadcrumb"><RouterLink to="/">首頁</RouterLink> / <RouterLink to="/courses">課程介紹</RouterLink> / {{course.name}}</p><div class="detail-title"><p class="eyebrow">FIND YOUR BALANCE</p><h1>{{course.name}}</h1><span class="badge">{{course.category}}</span><h2>從呼吸開始，建立身心的穩定與平衡</h2></div><div class="detail-grid"><div><img class="detail-image" src="/images/yoga-hero.png" alt="瑜珈練習氛圍示意"><section class="section"><h2>關於這堂練習</h2><p>為忙碌的生活留一段空白，在呼吸與伸展之間，感受當下的自己。歡迎依自己的身體狀況與老師討論合適的練習方式。</p><p class="muted">照片為品牌情境示意；實際課程內容與適合程度，請向授課老師確認。</p><div class="features three"><article><Sprout/><div><h3>循序練習</h3><p>尊重身體的節奏。</p></div></article><article><Heart/><div><h3>身心平衡</h3><p>練習覺察與呼吸。</p></div></article><article><Flower2/><div><h3>自在空間</h3><p>留一點時間給自己。</p></div></article></div></section><h2>練習前的小提醒</h2><ul class="reminders"><li>穿著舒適、方便活動的衣物。</li><li>攜帶飲用水與毛巾。</li><li>如有身體不適或特殊狀況，請提前告知老師。</li><li>體驗申請需經工作室確認，送出後尚未保留名額。</li></ul></div><aside><div class="panel booking"><h3>開始你的練習</h3><p><UserRound :size="18"/>{{course.teacher}} 老師</p><p><MapPin :size="18"/>{{course.location}}</p><p>整期費用 NT$ {{money(course.termPrice)}}</p><template v-if="next"><hr><p><CalendarDays :size="18"/>近期場次</p><h3>{{date(next.startsAt)}}</h3><p>{{time(next.startsAt)}} – {{time(next.endsAt)}}</p><span class="badge">{{next.enrolled}} / {{next.capacity}} 人</span><RouterLink v-if="next.enrolled<next.capacity" class="button" :to="`/trial?session=${next.id}`">申請體驗 <ArrowRight :size="17"/></RouterLink></template><p v-else>目前沒有近期公開場次。</p><RouterLink class="button outline" to="/schedule">查看公開課表</RouterLink><p v-if="error" class="error">{{error}}</p></div></aside></div></section><p v-else class="container empty">查無此公開課程，或課程已停止公開。<RouterLink to="/courses">返回課程列表</RouterLink></p></template>
